with objects as (select 'claims' as object_group,id,payload from (
        select c.claim_id::text,
          jsonb_build_object(
            'claim',to_jsonb(c),
            'territorial_practice',(select to_jsonb(x) from atlas.territorial_practice_claim x where x.claim_id=c.claim_id),
            'external_participation',(select to_jsonb(x) from atlas.external_participation_claim x where x.claim_id=c.claim_id),
            'legal_event',(select to_jsonb(x) from atlas.legal_event x where x.claim_id=c.claim_id),
            'actor_attribute',(select to_jsonb(x) from atlas.actor_attribute_claim x where x.claim_id=c.claim_id),
            'claim_sources',coalesce((select jsonb_agg(to_jsonb(x) order by x.claim_source_id) from atlas.claim_source x where x.claim_id=c.claim_id),'[]'::jsonb),
            'asserted_intervals',coalesce((select jsonb_agg(to_jsonb(x) order by x.claim_asserted_interval_id) from atlas.claim_asserted_interval x where x.claim_id=c.claim_id),'[]'::jsonb),
            'evidence_loci',coalesce((select jsonb_agg(to_jsonb(x) order by x.spatial_entity_id) from atlas.claim_evidence_locus x where x.claim_id=c.claim_id),'[]'::jsonb),
            'inference_extents',coalesce((select jsonb_agg(to_jsonb(x) order by x.spatial_entity_id) from atlas.claim_inference_extent x where x.claim_id=c.claim_id),'[]'::jsonb),
            'practice_facets',coalesce((select jsonb_agg(to_jsonb(x) order by x.practice_facet_assertion_id) from atlas.practice_facet_assertion x where x.claim_id=c.claim_id),'[]'::jsonb),
            'spatial_relations',coalesce((select jsonb_agg(to_jsonb(x) order by x.spatial_relation_id) from atlas.spatial_relation x where x.claim_id=c.claim_id),'[]'::jsonb),
            'voyage_owners',coalesce((select jsonb_agg(to_jsonb(x) order by x.voyage_owner_id) from atlas.voyage_owner x where x.claim_id=c.claim_id),'[]'::jsonb),
            'voyage_finance',coalesce((select jsonb_agg(to_jsonb(x) order by x.voyage_finance_id) from atlas.voyage_finance x where x.claim_id=c.claim_id),'[]'::jsonb),
            'voyage_stops',coalesce((select jsonb_agg(to_jsonb(x) order by x.voyage_stop_id) from atlas.voyage_stop x where x.claim_id=c.claim_id),'[]'::jsonb)
          )
        from atlas.claim c
        where c.claim_id=any(ARRAY['04cdf6ea-5b43-4f44-94a4-04b720ac7a2a','0bcc8c08-8226-5e4b-9f27-d69276f239de','0fa340fd-b595-4c48-aee6-71e5e235212e','12befe4d-3438-4989-b576-51581c470db0','1420ab66-9065-58c2-a5a8-edb94ddf16f0','1b912c74-1cf0-50d6-be5a-5270b9003536','1d3a5062-fd30-5d04-ae36-848857d87f6d','1d707382-b0b8-479d-81e3-efcea01c4ab0','1e2a16d7-456b-51c4-a4bd-b8540f7b5a6c','1eb1cd9a-c3ea-5a01-b5e9-6e27ae603361','1f865a88-6b27-4aa6-900f-813839856e6b','2945d4c3-d786-549a-baf9-fdfba54a978e','2acf6535-8b12-5cb1-abe6-c18d81824f08','2b456d9f-be09-4844-8899-286bd13464cb','2bfd9d51-b1fa-5abd-89c9-f60e8b856616','30c0a7dc-d941-5588-bfea-f55961c0373f','344f8c6d-b81f-5f2b-9c05-d764cfb25e08','363c68a1-3f99-508f-b5b5-d54bd94312a4','365e6258-f03f-4677-b775-cd5a9f18414a','383ef0e4-1ee1-48ae-8ca9-261622b95e1a','3b04340f-b830-48d1-9879-0f1b804e26c8','3b99b585-f295-54da-be2c-5927e421c169','450469cf-fe27-5e94-89c9-4d397be4b305','45a5e451-4ac0-5c37-8fdc-e60d524f46a8','47175a77-76bb-4a92-ac3c-cb22b7a8131f','4897a70a-0286-4281-9b65-68901135c993','51063cdb-f485-47c9-9056-e374476632dd','53405178-e879-4ef2-a12d-3cfcc0ad55f6','5779425a-f701-54a9-a984-b217feddecb0','58d69227-01e8-5d47-aba4-f3f96cea4230','5ceb9d5c-9766-4663-a12b-d663186293dc','5ed542f3-bb66-567d-9e3a-1235f48e7881','60f28ab3-2f20-4490-843b-c03a727d2c1d','63dda32b-6c3e-4b3e-9c5a-36596e6cdc1b','65963a31-a310-572c-9c58-2a0533f90fb5','687bed4f-281e-4821-bc23-1e75cb65dd99','70fb14f7-9fe0-4470-b53d-e42b7e98e5bd','7b467073-fd7f-4c58-b525-0b12c93cf8b4','7d503f54-1342-4ff8-a44d-f6a0f243df28','7f573935-45c9-4746-ac6a-6afe47bafbdd','8077abf3-f506-4bb1-908a-4aa5abd12369','80d955b5-9788-5ac8-b270-bbde157cb9d9','85bb684d-0aad-5410-a466-d3aad7f49c6f','85ed4143-2d4a-5baf-989c-d4c94897d527','8691d038-1683-5331-bccb-e7a189cdd229','88e48d2e-5b06-5b37-80bb-82e07db36a3f','896a3720-d871-495e-b23e-c24d7dde3039','8ca05e73-9282-5c42-90b1-8ccc215c27ee','8f853ded-eb39-432e-97c6-0715feaec950','94a4cb96-0300-4dbc-ae79-27318e71a50b','a076909a-3588-