        order by c.claim_id
        ) x(id,payload) union all select 'actors' as object_group,id,payload from (
        select a.actor_id::text,
          jsonb_build_object(
            'actor',to_jsonb(a),
            'names',coalesce((select jsonb_agg(to_jsonb(n) order by n.actor_name_id) from atlas.actor_name n where n.actor_id=a.actor_id),'[]'::jsonb)
          )
        from atlas.actor a
        where a.actor_id=any(ARRAY['2625aede-403a-578a-a7b9-13896729a058','50cbe83a-aa79-5935-bacb-84de9daf0997','6c564521-cca9-5991-8a78-c5bb1408aacd','888f5a40-a784-5af0-b103-8432fa748856','9b204811-95f4-5c27-938e-47534b9fb52b','9de3ff18-30c5-5778-ab2e-c0f0bbf2a8dc','aae15780-2d77-5119-a19c-9b5d9b0f9af0','c0ef1e15-8ed2-5ca5-900e-f092b393941c','c348a97f-0b48-5f8c-8bb3-6f480b620715','cd080ca3-ec51-5aa4-84af-1232bcd4c383','cf06c139-59f5-5395-b6fb-72c0b3597b6b']::uuid[])
