        ) x(id,payload) union all select 'voyages' as object_group,id,payload from (
        select v.voyage_id::text,
          jsonb_build_object(
            'voyage',to_jsonb(v),
            'owners',coalesce((select jsonb_agg(to_jsonb(x) order by x.voyage_owner_id) from atlas.voyage_owner x where x.voyage_id=v.voyage_id),'[]'::jsonb),
            'finance',coalesce((select jsonb_agg(to_jsonb(x) order by x.voyage_finance_id) from atlas.voyage_finance x where x.voyage_id=v.voyage_id),'[]'::jsonb),
            'stops',coalesce((select jsonb_agg(to_jsonb(x) order by x.voyage_stop_id) from atlas.voyage_stop x where x.voyage_id=v.voyage_id),'[]'::jsonb)
          )
        from atlas.voyage v
        where v.voyage_id=any(ARRAY['1a2cabb1-0e11-57ce-915d-7600e8fcf402','42408515-32fb-5149-9b1f-66e386c774a1','42e429b1-2d40-55b3-9e04-5df40c86562e','6b2c03cd-caa4-50ed-a8fd-aa02397fb0fa','8e2fe249-de8f-5f8e-b5ce-1405c10cdfc1','b9e23942-e5a9-53aa-9117-fbce136073b9','d4f71c52-23e2-570f-be13-ac3bc39fe3ad','f89d0865-1e74-5155-b457-10a884a83439']::uuid[])
